---
import type { HTMLAttributes } from "astro/types"

import { cn } from "@/lib/utils"

type Props = HTMLAttributes<"textarea">

const {
  class: className,
  "data-slot": dataSlot = "textarea",
  ...props
} = Astro.props
---

<textarea
  data-slot={dataSlot}
  class={cn(
    "border-transparent border-b-input bg-transparent focus-visible:border-b-ring aria-invalid:border-b-destructive dark:aria-invalid:border-b-destructive/50 resize-none rounded-none border px-0 py-3 text-base transition-[color,border-color] md:text-sm placeholder:text-muted-foreground flex field-sizing-content min-h-16 w-full outline-none disabled:cursor-not-allowed disabled:opacity-50",
    className
  )}
  {...props}
>
</textarea>
